import type { Session } from '../../lib/session';

export interface ProfileData {
  name: string;
  phone: string;
  role: 'employer' | 'worker';
  employerId: string;
  photoUrl?: string;
  verified?: boolean;
  address?: string;
  latitude?: number | null;
  longitude?: number | null;
}

/** Masks a phone number: keeps first 2 and last 2 digits visible.
 *  e.g. "9876543210" → "98XXXXXX10"  */
export function maskPhone(phone: string): string {
  if (phone.length <= 4) return phone;
  const visible = 2;
  return (
    phone.slice(0, visible) +
    'X'.repeat(Math.max(0, phone.length - visible * 2)) +
    phone.slice(-visible)
  );
}

/** Returns a 0–100 integer representing profile completeness.
 *  Fields: name, phone, address, coords → each worth 25 points. */
export function computeCompletion(profile: ProfileData): number {
  let score = 0;
  if (profile.name.trim()) score += 25;
  if (profile.phone.trim()) score += 25;
  if (profile.address?.trim()) score += 25;
  if (profile.latitude != null && profile.longitude != null) score += 25;
  return score;
}

